const CATS=[["verf",{"de":"Verfahren & Fristen","tr":"İşlemler ve süreler","bg":"Процедури и срокове","ar":"الإجراءات والمهل","uk":"Процедури й строки","pl":"Procedury i terminy","en":"Procedures & deadlines","el":"Διαδικασίες & προθεσμίες","fr":"Démarches & délais","nl":"Procedures & termijnen","ro":"Proceduri și termene","es":"Trámites y plazos","ku":"Pêvajo û dem"},"#3347F5"],["geld",{"de":"Geld & Leistungen","tr":"Para ve yardımlar","bg":"Пари и помощи","ar":"المال والمساعدات","uk":"Гроші та допомога","pl":"Pieniądze i świadczenia","en":"Money & benefits","el":"Χρήματα & παροχές","fr":"Argent & prestations","nl":"Geld & uitkeringen","ro":"Bani și prestații","es":"Dinero y prestaciones","ku":"Pere û alîkarî"},"#0B8A66"],["wohn",{"de":"Wohnen & Melden","tr":"Konut ve kayıt","bg":"Жилище и адресна регистрация","ar":"السكن والتسجيل","uk":"Житло й реєстрація","pl":"Mieszkanie i meldunek","en":"Housing & registration","el":"Κατοικία & δήλωση διεύθυνσης","fr":"Logement & domicile","nl":"Wonen & inschrijving","ro":"Locuință și domiciliu","es":"Vivienda y empadronamiento","ku":"Xanî û qeyd"},"#C77700"],["aufenth",{"de":"Aufenthalt","tr":"Oturum","bg":"Пребиваване","ar":"الإقامة","uk":"Перебування","pl":"Pobyt","en":"Residence","el":"Διαμονή","fr":"Séjour","nl":"Verblijf","ro":"Ședere","es":"Residencia","ku":"Mayîn"},"#B8357F"],["gesund",{"de":"Gesundheit & Versicherung","tr":"Sağlık ve sigorta","bg":"Здраве и осигуровки","ar":"الصحة والتأمين","uk":"Здоров'я та страхування","pl":"Zdrowie i ubezpieczenie","en":"Health & insurance","el":"Υγεία & ασφάλιση","fr":"Santé & assurance","nl":"Gezondheid & verzekering","ro":"Sănătate și asigurare","es":"Salud y seguro","ku":"Tenduristî û sîgorte"},"#2B6FD6"],["arbeit",{"de":"Arbeit & Steuern","tr":"İş ve vergi","bg":"Работа и данъци","ar":"العمل والضرائب","uk":"Робота й податки","pl":"Praca i podatki","en":"Work & tax","el":"Εργασία & φόροι","fr":"Travail & impôts","nl":"Werk & belasting","ro":"Muncă și impozite","es":"Trabajo e impuestos","ku":"Kar û bac"},"#6B4FD8"]];
const W=[{"w":"Bescheid","a":"der","c":"verf","g":{"tr":"karar (resmî yazı)","bg":"решение (официално)","ar":"قرار رسمي","uk":"рішення (офіційне)","pl":"decyzja (urzędowa)","en":"official decision","el":"απόφαση (υπηρεσίας)","fr":"décision (officielle)","nl":"besluit (officieel)","ro":"decizie (oficială)","es":"resolución (oficial)","ku":"biryara fermî"},"d":{"de":"Eine schriftliche Entscheidung eines Amtes, z. B. ob Sie Geld bekommen. Am Ende steht, wie und bis wann Sie widersprechen können.","tr":"Bir dairenin yazılı kararı, örneğin size para verilip verilmeyeceği. Sonunda nasıl ve ne zamana kadar itiraz edebileceğiniz yazar.","bg":"Писмено решение на служба, напр. дали получавате пари. Накрая пише как и до кога можете да възразите.","ar":"قرار مكتوب من دائرة رسمية، مثلاً هل ستحصل على مال. في آخره مكتوب كيف ومتى يمكنك الاعتراض.","uk":"Письмове рішення установи, напр. чи отримаєте ви гроші. Наприкінці сказано, як і до коли можна заперечити.","pl":"Pisemna decyzja urzędu, np. czy dostaniesz pieniądze. Na końcu jest napisane, jak i do kiedy możesz się odwołać.","en":"A written decision by an authority, e.g. whether you get money. At the end it says how and by when you can object.","el":"Γραπτή απόφαση μιας υπηρεσίας, π.χ. αν θα πάρετε χρήματα. Στο τέλος γράφει πώς και μέχρι πότε μπορείτε να κάνετε ένσταση.","fr":"Une décision écrite d'une administration, p. ex. si vous recevez de l'argent. À la fin, il est indiqué comment et jusqu'à quand contester.","nl":"Een schriftelijke beslissing van een instantie, bijv. of u geld krijgt. Aan het eind staat hoe en tot wanneer u bezwaar kunt maken.","ro":"O decizie scrisă a unei autorități, de ex. dacă primiți bani. La final scrie cum și până când puteți face contestație.","es":"Una decisión escrita de una oficina, p. ej. si recibes dinero. Al final pone cómo y hasta cuándo puedes recurrir.","ku":"Biryara nivîskî ya dezgehekê, mînak tu pere distînî an na. Di dawiyê de nivîsandî ye ka çawa û heta kengê dikarî îtîraz bikî."},"x":"Mit diesem Bescheid bewilligen wir Ihnen Leistungen für die Zeit vom 01.01. bis 31.12.","l":"j3"},
{"w":"Widerspruch","a":"der","c":"verf","g":{"tr":"itiraz","bg":"възражение","ar":"اعتراض","uk":"заперечення","pl":"sprzeciw","en":"objection","el":"ένσταση","fr":"recours","nl":"bezwaar","ro":"contestație","es":"recurso","ku":"îtîraz"},"d":{"de":"Damit wehren Sie sich schriftlich gegen einen Bescheid. Frist: meist 1 Monat ab Bekanntgabe. Die Begründung können Sie nachreichen.","tr":"Bir karara yazılı olarak karşı çıkmanızdır. Süre: genelde tebliğden itibaren 1 ay. Gerekçeyi sonradan gönderebilirsiniz.","bg":"Писменото ви несъгласие с решение. Срок: обикновено 1 месец от връчването. Обосновката може да изпратите по-късно.","ar":"اعتراضك المكتوب على قرار. المهلة: عادةً شهر واحد من التبليغ. يمكنك إرسال الأسباب لاحقاً.","uk":"Ваше письмове незгодження з рішенням. Строк: зазвичай 1 місяць від повідомлення. Обґрунтування можна надіслати пізніше.","pl":"Twój pisemny sprzeciw wobec decyzji. Termin: zwykle 1 miesiąc od doręczenia. Uzasadnienie można dosłać później.","en":"Your written challenge to a decision. Deadline: usually 1 month from notification. You can send the reasons later.","el":"Η γραπτή αντίρρησή σας σε μια απόφαση. Προθεσμία: συνήθως 1 μήνας από την κοινοποίηση. Την αιτιολογία μπορείτε να τη στείλετε αργότερα.","fr":"Votre contestation écrite d'une décision. Délai : en général 1 mois après la notification. Vous pouvez envoyer les motifs plus tard.","nl":"Uw schriftelijke tegenspraak tegen een besluit. Termijn: meestal 1 maand na bekendmaking. De motivering kunt u later sturen.","ro":"Opoziția dumneavoastră scrisă la o decizie. Termen: de regulă 1 lună de la comunicare. Motivarea o puteți trimite mai târziu.","es":"Tu oposición por escrito a una resolución. Plazo: normalmente 1 mes desde la notificación. Los motivos puedes enviarlos después.","ku":"Îtîraza te ya nivîskî li dijî biryarekê. Dem: bi gelemperî 1 meh ji ragihandinê. Sedeman dikarî paşê bişînî."},"x":"Gegen diesen Bescheid kann innerhalb eines Monats nach Bekanntgabe Widerspruch erhoben werden.","l":"j1","f":true},
{"w":"Frist","a":"die","c":"verf","g":{"tr":"süre / son tarih","bg":"срок","ar":"مهلة","uk":"строк","pl":"termin","en":"deadline","el":"προθεσμία","fr":"délai","nl":"termijn","ro":"termen","es":"plazo","ku":"dema dawî"},"d":{"de":"Der Zeitraum, bis zu dem Sie etwas tun müssen. Wer die Frist verpasst, verliert oft Rechte oder Geld.","tr":"Bir şeyi yapmanız gereken son tarih. Süreyi kaçıran çoğu zaman hak veya para kaybeder.","bg":"Датата, до която трябва да действате. Пропуснатият срок често значи загуба на права или пари.","ar":"التاريخ الذي يجب أن تتصرف قبله. تفويت المهلة يعني غالباً فقدان حقوق أو مال.","uk":"Дата, до якої треба діяти. Пропущений строк часто означає втрату прав або грошей.","pl":"Data, do której musisz coś zrobić. Przekroczenie terminu często oznacza utratę praw lub pieniędzy.","en":"The date by which you must act. Missing a deadline often means losing rights or money.","el":"Η ημερομηνία μέχρι την οποία πρέπει να ενεργήσετε. Αν τη χάσετε, συχνά χάνετε δικαιώματα ή χρήματα.","fr":"La date avant laquelle vous devez agir. Un délai manqué fait souvent perdre des droits ou de l'argent.","nl":"De datum waarvoor u iets moet doen. Wie een termijn mist, verliest vaak rechten of geld.","ro":"Data până la care trebuie să acționați. Cine ratează termenul pierde adesea drepturi sau bani.","es":"La fecha antes de la cual debes actuar. Quien pierde un plazo a menudo pierde derechos o dinero.","ku":"Dîroka ku divê heta wê tiştek bikî. Kî dem derbas bike, gelek caran maf an pere winda dike."},"x":"Bitte reichen Sie die Unterlagen bis zum 15.12. ein. Nach Ablauf der Frist entscheiden wir nach Aktenlage.","f":true},
{"w":"Anhörung","a":"die","c":"verf","g":{"tr":"dinlenme (görüş bildirme)","bg":"изслушване","ar":"استماع (إبداء الرأي)","uk":"заслуховування","pl":"wysłuchanie","en":"hearing (your say)","el":"ακρόαση","fr":"audition (droit d'être entendu)","nl":"hoorzitting (zienswijze)","ro":"audiere","es":"audiencia (trámite de alegaciones)","ku":"guhdarîkirin"},"d":{"de":"Bevor das Amt etwas Nachteiliges entscheidet, dürfen Sie Ihre Sicht schildern. Antworten Sie innerhalb der genannten Frist.","tr":"Daire aleyhinize bir karar vermeden önce görüşünüzü yazabilirsiniz. Belirtilen süre içinde cevap verin.","bg":"Преди службата да реши нещо против вас, можете да изложите позицията си. Отговорете в посочения срок.","ar":"قبل أن تقرر الدائرة شيئاً ضدك يمكنك عرض رأيك. أجب خلال المهلة المذكورة.","uk":"Перш ніж установа ухвалить невигідне для вас рішення, ви можете висловитися. Відповідайте у вказаний строк.","pl":"Zanim urząd zdecyduje na twoją niekorzyść, możesz przedstawić swoje stanowisko. Odpowiedz w podanym terminie.","en":"Before the office decides against you, you may give your view. Reply within the stated deadline.","el":"Πριν η υπηρεσία αποφασίσει κάτι εις βάρος σας, μπορείτε να πείτε τη γνώμη σας. Απαντήστε εντός της προθεσμίας.","fr":"Avant que l'administration décide contre vous, vous pouvez donner votre avis. Répondez dans le délai indiqué.","nl":"Voordat de instantie iets in uw nadeel beslist, mag u uw kant vertellen. Antwoord binnen de genoemde termijn.","ro":"Înainte ca autoritatea să decidă ceva în defavoarea dumneavoastră, vă puteți spune punctul de vedere. Răspundeți în termenul dat.","es":"Antes de que la oficina decida algo en tu contra, puedes dar tu versión. Responde dentro del plazo indicado.","ku":"Berî ku dezgeh li dijî te biryarê bide, tu dikarî nêrîna xwe bibêjî. Di dema diyarkirî de bersiv bide."},"x":"Bevor wir entscheiden, geben wir Ihnen Gelegenheit zur Stellungnahme (Anhörung).","f":true},
{"w":"Aktenzeichen","a":"das","c":"verf","g":{"tr":"dosya numarası","bg":"номер на преписката","ar":"رقم الملف","uk":"номер справи","pl":"sygnatura sprawy","en":"file number","el":"αριθμός φακέλου","fr":"numéro de dossier","nl":"dossiernummer","ro":"număr de dosar","es":"número de expediente","ku":"hejmara dosyayê"},"d":{"de":"Die Nummer Ihres Vorgangs beim Amt. Schreiben Sie sie auf jeden Brief, damit er schnell zugeordnet wird.","tr":"Dairedeki işleminizin numarası. Her mektuba yazın, böylece hızlı eşleştirilir.","bg":"Номерът на вашия случай в службата. Пишете го на всяко писмо, за да бъде намерен бързо.","ar":"رقم معاملتك لدى الدائرة. اكتبه على كل رسالة لتُربط بملفك بسرعة.","uk":"Номер вашої справи в установі. Пишіть його в кожному листі, щоб лист швидко знайшли.","pl":"Numer twojej sprawy w urzędzie. Podawaj go w każdym piśmie, by szybko je przypisano.","en":"The number of your case at the office. Put it on every letter so it is matched quickly.","el":"Ο αριθμός της υπόθεσής σας στην υπηρεσία. Γράψτε τον σε κάθε επιστολή για να βρεθεί γρήγορα.","fr":"Le numéro de votre dossier à l'administration. Indiquez-le sur chaque lettre pour qu'elle soit vite traitée.","nl":"Het nummer van uw zaak bij de instantie. Zet het op elke brief zodat die snel wordt gekoppeld.","ro":"Numărul cazului dumneavoastră la autoritate. Scrieți-l pe fiecare scrisoare ca să fie găsit repede.","es":"El número de tu caso en la oficina. Escríbelo en cada carta para que la asignen rápido.","ku":"Hejmara karê te li dezgehê. Wê li ser her nameyê binivîse da ku zû were dîtin."},"x":"Bitte geben Sie bei jeder Rückfrage unser Aktenzeichen an."},
{"w":"Rechtsbehelfsbelehrung","a":"die","c":"verf","g":{"tr":"itiraz yolları bilgisi","bg":"указание за обжалване","ar":"إرشاد بطرق الطعن","uk":"роз'яснення порядку оскарження","pl":"pouczenie o środkach odwoławczych","en":"instructions on legal remedies","el":"οδηγίες για ένδικα μέσα","fr":"indication des voies de recours","nl":"rechtsmiddelenclausule","ro":"instrucțiuni privind căile de atac","es":"instrucciones sobre recursos","ku":"agahdariya rêyên îtîrazê"},"d":{"de":"Der Abschnitt am Ende eines Bescheids: Er sagt, wie, wo und bis wann Sie sich wehren können. Fehlt er oder ist er falsch, gilt meist 1 Jahr.","tr":"Kararın sonundaki bölüm: nasıl, nereye ve ne zamana kadar itiraz edeceğinizi söyler. Eksik veya yanlışsa genelde 1 yıl geçerlidir.","bg":"Частта в края на решението: как, къде и до кога можете да го обжалвате. Ако липсва или е грешна, обикновено важи 1 година.","ar":"الفقرة في آخر القرار: كيف وأين ومتى يمكنك الطعن. إذا كانت ناقصة أو خاطئة فالمهلة عادةً سنة.","uk":"Розділ наприкінці рішення: як, куди й до коли можна оскаржити. Якщо його немає або він хибний, зазвичай діє 1 рік.","pl":"Część na końcu decyzji: jak, gdzie i do kiedy możesz się odwołać. Jeśli jej brak lub jest błędna, zwykle obowiązuje 1 rok.","en":"The section at the end of a decision: how, where and by when you can challenge it. If it is missing or wrong, usually 1 year applies.","el":"Το τμήμα στο τέλος της απόφασης: πώς, πού και μέχρι πότε μπορείτε να την προσβάλετε. Αν λείπει ή είναι λάθος, ισχύει συνήθως 1 χρόνος.","fr":"La partie à la fin de la décision : comment, où et jusqu'à quand la contester. Si elle manque ou est erronée, c'est en général 1 an.","nl":"Het stuk aan het eind van een besluit: hoe, waar en tot wanneer u het kunt aanvechten. Ontbreekt het of is het fout, dan geldt meestal 1 jaar.","ro":"Partea de la finalul deciziei: cum, unde și până când o puteți ataca. Dacă lipsește sau e greșită, de regulă se aplică 1 an.","es":"La parte al final de la resolución: cómo, dónde y hasta cuándo puedes recurrir. Si falta o es errónea, suele valer 1 año.","ku":"Beşa di dawiya biryarê de: çawa, li ku û heta kengê dikarî îtîraz bikî. Heke tune be an şaş be, bi gelemperî 1 sal derbas dibe."},"x":"Rechtsbehelfsbelehrung: Gegen diesen Bescheid kann innerhalb eines Monats Widerspruch erhoben werden.","f":true},
{"w":"Bekanntgabe","a":"die","c":"verf","g":{"tr":"tebliğ","bg":"връчване","ar":"تاريخ التبليغ","uk":"день повідомлення","pl":"doręczenie","en":"date of notification","el":"κοινοποίηση","fr":"notification","nl":"bekendmaking","ro":"comunicare","es":"notificación","ku":"roja ragihandinê"},"d":{"de":"Der Tag, ab dem ein Bescheid als zugestellt gilt. Bei normaler Post ist das seit 2025 meist der 4. Tag nach dem Datum des Briefs.","tr":"Kararın size ulaşmış sayıldığı gün. Normal postada 2025'ten beri genelde mektup tarihinden sonraki 4. gün.","bg":"Денят, в който решението се смята за получено. При обикновена поща от 2025 г. обикновено е 4-ият ден след датата на писмото.","ar":"اليوم الذي يُعتبر فيه القرار مستلَماً. في البريد العادي منذ 2025 عادةً اليوم الرابع بعد تاريخ الرسالة.","uk":"День, коли рішення вважається отриманим. Для звичайної пошти з 2025 р. це зазвичай 4-й день після дати листа.","pl":"Dzień, w którym decyzję uznaje się za doręczoną. Przy zwykłej poczcie od 2025 r. to zwykle 4. dzień po dacie pisma.","en":"The day a decision counts as received. For ordinary post, since 2025 this is usually the 4th day after the letter's date.","el":"Η ημέρα που η απόφαση θεωρείται ότι παραλήφθηκε. Με απλό ταχυδρομείο, από το 2025 συνήθως η 4η ημέρα μετά την ημερομηνία της επιστολής.","fr":"Le jour où une décision est réputée reçue. Par courrier ordinaire, depuis 2025, en général le 4e jour après la date de la lettre.","nl":"De dag waarop een besluit als ontvangen geldt. Bij gewone post sinds 2025 meestal de 4e dag na de datum van de brief.","ro":"Ziua în care decizia se consideră primită. Prin poștă obișnuită, din 2025 de regulă a 4-a zi după data scrisorii.","es":"El día en que la resolución se considera recibida. Por correo normal, desde 2025 suele ser el 4.º día después de la fecha de la carta.","ku":"Roja ku biryar wek gihîştî tê hesibandin. Bi posta asayî ji 2025an vir ve bi gelemperî roja 4an piştî dîroka nameyê ye."},"x":"Der Bescheid gilt am vierten Tag nach der Aufgabe zur Post als bekannt gegeben.","f":true},
{"w":"Mitwirkungspflicht","a":"die","c":"verf","g":{"tr":"katılım yükümlülüğü","bg":"задължение за съдействие","ar":"واجب التعاون","uk":"обов'язок сприяння","pl":"obowiązek współdziałania","en":"duty to cooperate","el":"υποχρέωση συνεργασίας","fr":"obligation de coopérer","nl":"medewerkingsplicht","ro":"obligația de cooperare","es":"deber de colaboración","ku":"erka hevkariyê"},"d":{"de":"Sie müssen dem Amt die nötigen Angaben und Unterlagen geben. Tun Sie das nicht rechtzeitig, kann die Leistung abgelehnt oder gestoppt werden.","tr":"Daireye gerekli bilgi ve belgeleri vermek zorundasınız. Zamanında vermezseniz yardım reddedilebilir veya durdurulabilir.","bg":"Трябва да дадете на службата нужните данни и документи. Ако не го направите навреме, помощта може да бъде отказана или спряна.","ar":"يجب أن تعطي الدائرة المعلومات والمستندات اللازمة. إن لم تفعل في الوقت المحدد قد تُرفض الإعانة أو تتوقف.","uk":"Ви мусите надати установі потрібні дані й документи. Якщо не встигнете, у допомозі можуть відмовити або її припинити.","pl":"Musisz przekazać urzędowi potrzebne informacje i dokumenty. Jeśli nie zrobisz tego na czas, świadczenie może zostać odmówione lub wstrzymane.","en":"You must give the office the information and documents it needs. If you don't in time, the benefit can be refused or stopped.","el":"Πρέπει να δώσετε στην υπηρεσία τα απαραίτητα στοιχεία και έγγραφα. Αν δεν το κάνετε εγκαίρως, η παροχή μπορεί να απορριφθεί ή να σταματήσει.","fr":"Vous devez fournir à l'administration les informations et documents nécessaires. Sinon, la prestation peut être refusée ou arrêtée.","nl":"U moet de instantie de nodige gegevens en documenten geven. Doet u dat niet op tijd, dan kan de uitkering worden geweigerd of gestopt.","ro":"Trebuie să dați autorității datele și documentele necesare. Dacă nu o faceți la timp, prestația poate fi refuzată sau oprită.","es":"Debes dar a la oficina los datos y documentos necesarios. Si no lo haces a tiempo, pueden denegar o suspender la prestación.","ku":"Divê tu agahî û belgeyên pêwîst bidî dezgehê. Heke di wextê xwe de nedî, alîkarî dikare were redkirin an rawestandin."},"x":"Wir weisen Sie auf Ihre Mitwirkungspflichten nach §§ 60 ff. SGB I hin.","f":true},
{"w":"Sachstandsanfrage","a":"die","c":"verf","g":{"tr":"durum sorgusu","bg":"запитване за статуса","ar":"استفسار عن الحالة","uk":"запит щодо стану","pl":"zapytanie o stan sprawy","en":"status inquiry","el":"ερώτηση για την πορεία","fr":"demande d'état d'avancement","nl":"navraag naar de stand","ro":"întrebare despre stadiu","es":"consulta sobre el estado","ku":"pirsîna rewşê"},"d":{"de":"Eine kurze Nachfrage, wie weit Ihr Antrag ist. Sinnvoll, wenn Sie lange keine Antwort bekommen.","tr":"Başvurunuzun ne durumda olduğunu soran kısa bir yazı. Uzun süre cevap gelmezse işe yarar.","bg":"Кратко писмо с въпрос докъде е заявлението ви. Полезно, ако дълго няма отговор.","ar":"رسالة قصيرة تسأل إلى أين وصل طلبك. مفيدة إذا لم يصلك رد لفترة طويلة.","uk":"Короткий лист із питанням, на якому етапі ваша заява. Корисно, якщо довго немає відповіді.","pl":"Krótkie pismo z pytaniem, na jakim etapie jest twój wniosek. Przydatne, gdy długo nie ma odpowiedzi.","en":"A short letter asking how far your application is. Useful if you have had no answer for a long time.","el":"Σύντομη επιστολή που ρωτά πού βρίσκεται η αίτησή σας. Χρήσιμη αν δεν έχετε απάντηση για πολύ καιρό.","fr":"Une courte lettre pour savoir où en est votre demande. Utile si vous n'avez pas de réponse depuis longtemps.","nl":"Een korte brief waarin u vraagt hoe ver uw aanvraag is. Handig als u lang geen antwoord krijgt.","ro":"O scrisoare scurtă prin care întrebați în ce stadiu este cererea. Utilă dacă nu primiți răspuns mult timp.","es":"Una carta breve para preguntar cómo va tu solicitud. Útil si llevas mucho tiempo sin respuesta.","ku":"Nameyeke kurt ku dipirse serlêdana te gihîştiye ku. Bi kêr tê heke demeke dirêj bersiv neyê."},"x":"Ihre Sachstandsanfrage vom 03.11. haben wir erhalten.","l":"bm4"},
{"w":"Akteneinsicht","a":"die","c":"verf","g":{"tr":"dosyayı inceleme","bg":"достъп до преписката","ar":"الاطلاع على الملف","uk":"ознайомлення зі справою","pl":"wgląd do akt","en":"access to your file","el":"πρόσβαση στον φάκελο","fr":"consultation du dossier","nl":"inzage in het dossier","ro":"consultarea dosarului","es":"acceso al expediente","ku":"dîtina dosyayê"},"d":{"de":"Sie dürfen Ihre Akte beim Amt ansehen, um zu wissen, worauf eine Entscheidung beruht. Das hilft oft bei einem Widerspruch.","tr":"Bir kararın neye dayandığını görmek için dairedeki dosyanıza bakabilirsiniz. İtirazda çoğu zaman yardımcı olur.","bg":"Можете да разгледате преписката си в службата, за да видите на какво се основава решението. Често помага при възражение.","ar":"يحق لك الاطلاع على ملفك لدى الدائرة لمعرفة أساس القرار. يساعد ذلك غالباً في الاعتراض.","uk":"Ви можете переглянути свою справу в установі, щоб знати, на чому ґрунтується рішення. Часто допомагає при запереченні.","pl":"Możesz przejrzeć swoje akta w urzędzie, by wiedzieć, na czym opiera się decyzja. Często pomaga przy sprzeciwie.","en":"You may look at your file at the office to see what a decision is based on. This often helps with an objection.","el":"Μπορείτε να δείτε τον φάκελό σας στην υπηρεσία για να ξέρετε σε τι βασίζεται η απόφαση. Συχνά βοηθά σε μια ένσταση.","fr":"Vous pouvez consulter votre dossier pour savoir sur quoi repose une décision. Souvent utile pour un recours.","nl":"U mag uw dossier bij de instantie inzien om te weten waarop een besluit berust. Helpt vaak bij een bezwaar.","ro":"Vă puteți consulta dosarul la autoritate ca să știți pe ce se bazează decizia. Ajută adesea la o contestație.","es":"Puedes ver tu expediente en la oficina para saber en qué se basa una resolución. Suele ayudar en un recurso.","ku":"Tu dikarî li dezgehê li dosyaya xwe binêrî da ku bizanî biryar li ser çi ye. Di îtîrazê de gelek caran dibe alîkar."},"x":"Gleichzeitig beantrage ich Akteneinsicht."},
{"w":"Antrag","a":"der","c":"verf","g":{"tr":"başvuru","bg":"заявление","ar":"طلب","uk":"заява","pl":"wniosek","en":"application","el":"αίτηση","fr":"demande","nl":"aanvraag","ro":"cerere","es":"solicitud","ku":"serlêdan"},"d":{"de":"Ihre schriftliche Bitte an ein Amt, z. B. um Geld oder eine Erlaubnis. Viele Leistungen gibt es erst ab dem Monat des Antrags.","tr":"Bir daireden yazılı talebiniz, örneğin para veya izin için. Birçok yardım ancak başvuru ayından itibaren ödenir.","bg":"Писмената ви молба към служба, напр. за пари или разрешение. Много помощи се плащат едва от месеца на заявлението.","ar":"طلبك المكتوب إلى دائرة، مثلاً للمال أو لتصريح. كثير من الإعانات تُدفع فقط من شهر تقديم الطلب.","uk":"Ваше письмове прохання до установи, напр. про гроші чи дозвіл. Багато виплат призначають лише з місяця подання.","pl":"Twoja pisemna prośba do urzędu, np. o pieniądze lub zezwolenie. Wiele świadczeń przysługuje dopiero od miesiąca złożenia wniosku.","en":"Your written request to an office, e.g. for money or a permit. Many benefits are only paid from the month you apply.","el":"Το γραπτό σας αίτημα σε υπηρεσία, π.χ. για χρήματα ή άδεια. Πολλές παροχές δίνονται μόνο από τον μήνα της αίτησης.","fr":"Votre requête écrite à une administration, p. ex. pour de l'argent ou une autorisation. Beaucoup de prestations ne sont versées qu'à partir du mois de la demande.","nl":"Uw schriftelijk verzoek aan een instantie, bijv. om geld of een vergunning. Veel uitkeringen krijgt u pas vanaf de maand van aanvraag.","ro":"Solicitarea dumneavoastră scrisă către o autoritate, de ex. pentru bani sau o aprobare. Multe prestații se plătesc doar din luna cererii.","es":"Tu petición escrita a una oficina, p. ej. de dinero o de un permiso. Muchas prestaciones solo se pagan desde el mes de la solicitud.","ku":"Daxwaza te ya nivîskî ji dezgehekê, mînak ji bo pere an destûrê. Gelek alîkarî tenê ji meha serlêdanê tên dayîn."},"x":"Ihr Antrag ist am 12.10. bei uns eingegangen."},
{"w":"Nachweis","a":"der","c":"verf","g":{"tr":"belge / kanıt","bg":"доказателство","ar":"إثبات / مستند","uk":"підтвердження / доказ","pl":"dowód / zaświadczenie","en":"proof / evidence","el":"αποδεικτικό","fr":"justificatif","nl":"bewijsstuk","ro":"dovadă","es":"justificante","ku":"belge / delîl"},"d":{"de":"Ein Dokument, das etwas beweist, z. B. Kontoauszug, Mietvertrag oder Lohnabrechnung. Schicken Sie Kopien, keine Originale.","tr":"Bir şeyi kanıtlayan belge, örneğin hesap dökümü, kira sözleşmesi veya maaş bordrosu. Aslını değil kopyasını gönderin.","bg":"Документ, който доказва нещо, напр. банково извлечение, договор за наем или фиш за заплата. Пращайте копия, не оригинали.","ar":"مستند يثبت شيئاً، مثل كشف حساب أو عقد إيجار أو قسيمة راتب. أرسل نسخاً لا الأصول.","uk":"Документ, що щось доводить, напр. виписка з рахунку, договір оренди чи розрахунковий листок. Надсилайте копії, не оригінали.","pl":"Dokument, który coś potwierdza, np. wyciąg z konta, umowa najmu lub pasek wypłaty. Wysyłaj kopie, nie oryginały.","en":"A document that proves something, e.g. a bank statement, tenancy contract or payslip. Send copies, not originals.","el":"Έγγραφο που αποδεικνύει κάτι, π.χ. κίνηση λογαριασμού, μισθωτήριο ή εκκαθαριστικό. Στείλτε αντίγραφα, όχι πρωτότυπα.","fr":"Un document qui prouve quelque chose, p. ex. relevé bancaire, bail ou fiche de paie. Envoyez des copies, pas les originaux.","nl":"Een document dat iets bewijst, bijv. bankafschrift, huurcontract of loonstrook. Stuur kopieën, geen originelen.","ro":"Un document care dovedește ceva, de ex. extras de cont, contract de închiriere sau fluturaș de salariu. Trimiteți copii, nu originale.","es":"Un documento que prueba algo, p. ej. extracto bancario, contrato de alquiler o nómina. Envía copias, no originales.","ku":"Belgeyek ku tiştekî îspat dike, wek dersa hesabê, peymana kirê an pusula meaşê. Kopiyan bişîne, ne orîjînalan."},"x":"Bitte fügen Sie einen Nachweis über Ihr Einkommen bei."},
{"w":"Einschreiben","a":"das","c":"verf","g":{"tr":"taahhütlü mektup","bg":"препоръчано писмо","ar":"رسالة مسجّلة","uk":"рекомендований лист","pl":"list polecony","en":"registered mail","el":"συστημένη επιστολή","fr":"lettre recommandée","nl":"aangetekende brief","ro":"scrisoare recomandată","es":"carta certificada","ku":"nameya qeydkirî"},"d":{"de":"Ein Brief mit Beleg der Post. So können Sie beweisen, dass Sie ihn abgeschickt haben – wichtig bei Fristen.","tr":"Postanın makbuz verdiği mektup. Gönderdiğinizi kanıtlarsınız – sürelerde önemli.","bg":"Писмо с разписка от пощата. Доказва, че сте го изпратили – важно при срокове.","ar":"رسالة بإيصال من البريد. تثبت أنك أرسلتها – مهم عند المهل.","uk":"Лист із квитанцією пошти. Доводить, що ви його надіслали, – важливо для строків.","pl":"List z potwierdzeniem nadania. Dowodzi, że go wysłałeś – ważne przy terminach.","en":"A letter with a post office receipt. It proves you sent it – important for deadlines.","el":"Επιστολή με απόδειξη του ταχυδρομείου. Αποδεικνύει ότι τη στείλατε – σημαντικό για προθεσμίες.","fr":"Une lettre avec reçu de la poste. Elle prouve l'envoi – important pour les délais.","nl":"Een brief met ontvangstbewijs van de post. Bewijst dat u hem verstuurde – belangrijk bij termijnen.","ro":"O scrisoare cu chitanță de la poștă. Dovedește că ați trimis-o – important pentru termene.","es":"Una carta con resguardo de correos. Prueba que la enviaste – importante para los plazos.","ku":"Nameyek bi wergirtina postê. Îspat dike ku te ew şandiye – ji bo deman girîng e."},"x":"Die Kündigung habe ich Ihnen per Einschreiben zugesandt."},
{"w":"Überprüfungsantrag","a":"der","c":"verf","g":{"tr":"yeniden inceleme başvurusu","bg":"молба за преразглеждане","ar":"طلب مراجعة","uk":"заява про перегляд","pl":"wniosek o ponowne rozpatrzenie","en":"request for review","el":"αίτηση επανεξέτασης","fr":"demande de réexamen","nl":"verzoek om herziening","ro":"cerere de reexaminare","es":"solicitud de revisión","ku":"serlêdana vekolînê"},"d":{"de":"Damit lassen Sie einen Bescheid prüfen, auch wenn die Widerspruchsfrist vorbei ist. Rückwirkend gibt es Geld oft nur für eine begrenzte Zeit.","tr":"İtiraz süresi geçmiş olsa da bir kararı yeniden kontrol ettirirsiniz. Geriye dönük para çoğu zaman sınırlı bir süre için verilir.","bg":"Така искате повторна проверка на решение, дори след срока за възражение. Пари със задна дата често има само за ограничен период.","ar":"تطلب به مراجعة قرار حتى بعد انتهاء مهلة الاعتراض. المال بأثر رجعي غالباً لفترة محدودة.","uk":"Ви просите перевірити рішення навіть після строку заперечення. Гроші заднім числом часто лише за обмежений період.","pl":"Prosisz o ponowne sprawdzenie decyzji nawet po terminie na sprzeciw. Wyrównanie wstecz często tylko za ograniczony czas.","en":"Asks the office to re-check a decision even after the objection deadline. Back payments are often limited in time.","el":"Ζητάτε να ελεγχθεί ξανά μια απόφαση, ακόμη κι αν πέρασε η προθεσμία ένστασης. Αναδρομικά χρήματα συχνά μόνο για περιορισμένο διάστημα.","fr":"Vous demandez de revoir une décision même après le délai de recours. Les rappels de paiement sont souvent limités dans le temps.","nl":"U laat een besluit opnieuw controleren, ook na de bezwaartermijn. Nabetaling geldt vaak maar voor een beperkte tijd.","ro":"Cereți reverificarea unei decizii chiar după termenul de contestație. Banii retroactivi sunt adesea limitați în timp.","es":"Pides revisar una resolución incluso después del plazo de recurso. Los atrasos suelen pagarse solo por un tiempo limitado.","ku":"Tu dixwazî biryarek ji nû ve were kontrolkirin, her çend dema îtîrazê derbas bûbe jî. Pereyê paşverû gelek caran tenê ji bo demeke sînorkirî ye."},"x":"Ich stelle einen Überprüfungsantrag nach § 44 SGB X.","f":true},
{"w":"Grundsicherungsgeld","a":"das","c":"geld","g":{"tr":"temel güvence ödeneği","bg":"основно социално подпомагане","ar":"إعانة الضمان الأساسي","uk":"базова соціальна допомога","pl":"podstawowe zabezpieczenie","en":"basic income support","el":"βασικό εισόδημα","fr":"revenu de base","nl":"basisuitkering","ro":"venit de bază","es":"ingreso básico","ku":"alîkariya bingehîn"},"d":{"de":"Die Leistung vom Jobcenter für Arbeitsuchende mit wenig Geld. Sie hieß früher Bürgergeld.","tr":"Jobcenter'in az parası olan iş arayanlara ödediği yardım. Eskiden Bürgergeld adını taşıyordu.","bg":"Помощта от Jobcenter за търсещи работа с малко пари. По-рано се казваше Bürgergeld.","ar":"إعانة الجوب سنتر للباحثين عن عمل ذوي الدخل القليل. كان اسمها سابقاً Bürgergeld.","uk":"Виплата Jobcenter для шукачів роботи з малими доходами. Раніше називалася Bürgergeld.","pl":"Świadczenie Jobcenter dla szukających pracy z małymi dochodami. Wcześniej nazywało się Bürgergeld.","en":"The Jobcenter benefit for job-seekers with little money. It used to be called Bürgergeld.","el":"Η παροχή του Jobcenter για αναζητούντες εργασία με λίγα χρήματα. Παλαιότερα λεγόταν Bürgergeld.","fr":"La prestation du Jobcenter pour les demandeurs d'emploi aux faibles revenus. Elle s'appelait autrefois Bürgergeld.","nl":"De uitkering van het Jobcenter voor werkzoekenden met weinig geld. Heette vroeger Bürgergeld.","ro":"Prestația Jobcenter pentru cei care caută de lucru și au puțini bani. Înainte se numea Bürgergeld.","es":"La prestación del Jobcenter para demandantes de empleo con pocos ingresos. Antes se llamaba Bürgergeld.","ku":"Alîkariya Jobcenter ji bo kesên ku kar digerin û pereyê wan kêm e. Berê navê wê Bürgergeld bû."},"x":"Ihr Anspruch auf Grundsicherungsgeld wurde neu berechnet.","l":"j2"},
{"w":"Weiterbewilligungsantrag","a":"der","c":"geld","g":{"tr":"devam başvurusu","bg":"заявление за продължаване","ar":"طلب التمديد","uk":"заява на продовження","pl":"wniosek o kontynuację","en":"renewal application","el":"αίτηση συνέχισης","fr":"demande de renouvellement","nl":"verlengingsaanvraag","ro":"cerere de continuare","es":"solicitud de renovación","ku":"serlêdana berdewamiyê"},"d":{"de":"Der Antrag, damit eine Leistung nach Ende des Bewilligungszeitraums weiterläuft. Stellen Sie ihn rechtzeitig vor dem Ablauf.","tr":"Ödeme dönemi bitince yardımın devam etmesi için yapılan başvuru. Süre bitmeden zamanında yapın.","bg":"Заявлението помощта да продължи след края на периода. Подайте го навреме, преди да изтече.","ar":"طلب استمرار الإعانة بعد انتهاء فترة الصرف. قدّمه في الوقت المناسب قبل انتهائها.","uk":"Заява, щоб виплата тривала після кінця періоду призначення. Подайте вчасно, до його закінчення.","pl":"Wniosek, by świadczenie było wypłacane dalej po końcu okresu przyznania. Złóż go na czas, przed upływem okresu.","en":"The application to keep a benefit going after the approval period ends. Submit it in good time before it runs out.","el":"Η αίτηση για να συνεχιστεί μια παροχή μετά το τέλος της περιόδου. Υποβάλετέ την εγκαίρως, πριν λήξει.","fr":"La demande pour que la prestation continue après la fin de la période. Déposez-la à temps, avant l'échéance.","nl":"De aanvraag om een uitkering na het einde van de periode door te laten lopen. Dien hem tijdig in, voor het afloopt.","ro":"Cererea ca prestația să continue după perioada de acordare. Depuneți-o la timp, înainte să expire.","es":"La solicitud para que la prestación siga tras el fin del periodo. Preséntala a tiempo, antes de que venza.","ku":"Serlêdan da ku alîkarî piştî dawiya demê berdewam bike. Berî ku dem biqede, di wextê xwe de bike."},"x":"Ihr Bewilligungszeitraum endet am 31.12. Bitte stellen Sie rechtzeitig einen Weiterbewilligungsantrag.","f":true},
{"w":"Bewilligungszeitraum","a":"der","c":"geld","g":{"tr":"ödeme dönemi","bg":"период на отпускане","ar":"فترة الصرف","uk":"період призначення","pl":"okres przyznania","en":"approval period","el":"περίοδος έγκρισης","fr":"période d'attribution","nl":"toekenningsperiode","ro":"perioada de acordare","es":"periodo de concesión","ku":"dema pejirandinê"},"d":{"de":"Die Zeit, für die eine Leistung bewilligt ist. Danach müssen Sie meist einen neuen Antrag stellen.","tr":"Yardımın onaylandığı dönem. Sonrasında genelde yeni başvuru gerekir.","bg":"Периодът, за който е отпусната помощта. След това обикновено трябва ново заявление.","ar":"الفترة التي وُوفق فيها على الإعانة. بعدها تحتاج عادةً إلى طلب جديد.","uk":"Період, на який призначено виплату. Після нього зазвичай потрібна нова заява.","pl":"Okres, na który przyznano świadczenie. Potem zwykle trzeba złożyć nowy wniosek.","en":"The period for which a benefit is approved. After that you usually need to apply again.","el":"Η περίοδος για την οποία εγκρίθηκε η παροχή. Μετά χρειάζεται συνήθως νέα αίτηση.","fr":"La période pour laquelle une prestation est accordée. Ensuite, il faut en général une nouvelle demande.","nl":"De periode waarvoor een uitkering is toegekend. Daarna is meestal een nieuwe aanvraag nodig.","ro":"Perioada pentru care s-a aprobat prestația. După aceea e nevoie de regulă de o cerere nouă.","es":"El periodo para el que se concede una prestación. Después normalmente hace falta una nueva solicitud.","ku":"Dema ku alîkarî ji bo wê hatiye pejirandin. Piştî wê bi gelemperî serlêdaneke nû pêwîst e."},"x":"Der Bewilligungszeitraum umfasst die Monate Januar bis Dezember."},
{"w":"Veränderungsmitteilung","a":"die","c":"geld","g":{"tr":"değişiklik bildirimi","bg":"съобщение за промяна","ar":"إبلاغ عن تغيير","uk":"повідомлення про зміни","pl":"zgłoszenie zmian","en":"notice of change","el":"δήλωση μεταβολής","fr":"déclaration de changement","nl":"wijzigingsmelding","ro":"notificare de modificare","es":"comunicación de cambios","ku":"ragihandina guhertinê"},"d":{"de":"Damit melden Sie dem Amt Änderungen, z. B. neue Arbeit, Umzug oder Geburt. Melden Sie sofort, sonst drohen Rückforderungen.","tr":"Daireye değişiklikleri bildirirsiniz, örneğin yeni iş, taşınma veya doğum. Hemen bildirin, yoksa geri ödeme istenebilir.","bg":"Съобщавате на службата промени, напр. нова работа, преместване или раждане. Веднага – иначе може да се наложи да връщате пари.","ar":"تُبلغ الدائرة بالتغييرات، مثل عمل جديد أو انتقال أو ولادة. أبلغ فوراً وإلا قد تُطالَب بإعادة المال.","uk":"Ви повідомляєте установу про зміни, напр. нову роботу, переїзд чи народження дитини. Одразу – інакше можуть вимагати повернення грошей.","pl":"Zgłaszasz urzędowi zmiany, np. nową pracę, przeprowadzkę czy narodziny dziecka. Od razu – inaczej grozi zwrot pieniędzy.","en":"You report changes to the office, e.g. a new job, a move or a birth. Report at once, or you may have to pay money back.","el":"Δηλώνετε στην υπηρεσία αλλαγές, π.χ. νέα δουλειά, μετακόμιση ή γέννηση. Αμέσως – αλλιώς μπορεί να σας ζητηθούν χρήματα πίσω.","fr":"Vous signalez des changements : nouvel emploi, déménagement, naissance. Tout de suite – sinon on peut vous réclamer de l'argent.","nl":"U meldt wijzigingen, bijv. nieuw werk, verhuizing of geboorte. Meteen – anders kan geld worden teruggevorderd.","ro":"Anunțați autoritatea despre schimbări, de ex. loc de muncă nou, mutare sau naștere. Imediat – altfel vi se pot cere bani înapoi.","es":"Comunicas cambios a la oficina, p. ej. nuevo trabajo, mudanza o nacimiento. Enseguida – si no, pueden reclamarte dinero.","ku":"Tu guhertinan ji dezgehê re dibêjî, wek karê nû, barkirin an zayîn. Yekser bibêje, wekî din dibe ku pere ji te were xwestin."},"x":"Bitte teilen Sie uns Änderungen umgehend mit dem Formular Veränderungsmitteilung mit.","l":"j2"},
{"w":"Rückforderung","a":"die","c":"geld","g":{"tr":"geri ödeme talebi","bg":"искане за връщане","ar":"طلب استرداد","uk":"вимога повернення","pl":"żądanie zwrotu","en":"repayment demand","el":"αίτημα επιστροφής","fr":"demande de remboursement","nl":"terugvordering","ro":"cerere de restituire","es":"reclamación de devolución","ku":"daxwaza vegerandinê"},"d":{"de":"Das Amt verlangt zu viel gezahltes Geld zurück. Prüfen Sie die Rechnung; gegen den Bescheid können Sie Widerspruch einlegen.","tr":"Daire fazla ödenen parayı geri ister. Hesabı kontrol edin; karara itiraz edebilirsiniz.","bg":"Службата иска обратно надплатени пари. Проверете сметката; срещу решението може да възразите.","ar":"تطالب الدائرة بإعادة مال دُفع زيادةً. افحص الحساب؛ يمكنك الاعتراض على القرار.","uk":"Установа вимагає повернути переплачені гроші. Перевірте розрахунок; на рішення можна подати заперечення.","pl":"Urząd żąda zwrotu nadpłaconych pieniędzy. Sprawdź wyliczenie; od decyzji możesz wnieść sprzeciw.","en":"The office asks for overpaid money back. Check the calculation; you can object to the decision.","el":"Η υπηρεσία ζητά πίσω χρήματα που πληρώθηκαν παραπάνω. Ελέγξτε τον υπολογισμό· μπορείτε να κάνετε ένσταση.","fr":"L'administration réclame un trop-perçu. Vérifiez le calcul ; vous pouvez contester la décision.","nl":"De instantie vraagt te veel betaald geld terug. Controleer de berekening; tegen het besluit kunt u bezwaar maken.","ro":"Autoritatea cere înapoi banii plătiți în plus. Verificați calculul; puteți contesta decizia.","es":"La oficina reclama dinero pagado de más. Revisa el cálculo; puedes recurrir la resolución.","ku":"Dezgeh pereyê zêde hatî dayîn paş dixwaze. Hesabê kontrol bike; li dijî biryarê dikarî îtîraz bikî."},"x":"Die überzahlten Leistungen in Höhe von 312,40 € sind zu erstatten.","f":true},
{"w":"Kostenbeitrag","a":"der","c":"geld","g":{"tr":"katkı payı","bg":"вноска (такса)","ar":"مساهمة (رسوم)","uk":"внесок (плата)","pl":"wkład własny (opłata)","en":"contribution (fee)","el":"συμμετοχή στο κόστος","fr":"participation aux frais","nl":"eigen bijdrage","ro":"contribuție proprie","es":"aportación propia","ku":"beşdariya lêçûnê"},"d":{"de":"Der Eigenanteil, den Sie zahlen, z. B. für den Integrationskurs. Mit wenig Einkommen können Sie eine Befreiung beantragen.","tr":"Sizin ödediğiniz pay, örneğin entegrasyon kursu için. Geliriniz azsa muafiyet isteyebilirsiniz.","bg":"Частта, която плащате сами, напр. за интеграционния курс. При нисък доход можете да поискате освобождаване.","ar":"الحصة التي تدفعها بنفسك، مثلاً لدورة الاندماج. إذا كان دخلك قليلاً يمكنك طلب الإعفاء.","uk":"Частка, яку ви платите самі, напр. за інтеграційний курс. За малого доходу можна просити звільнення.","pl":"Część, którą płacisz sam, np. za kurs integracyjny. Przy niskich dochodach możesz wnioskować o zwolnienie.","en":"The share you pay yourself, e.g. for the integration course. On a low income you can apply for an exemption.","el":"Το μερίδιο που πληρώνετε εσείς, π.χ. για το μάθημα ένταξης. Με χαμηλό εισόδημα μπορείτε να ζητήσετε απαλλαγή.","fr":"La part que vous payez vous-même, p. ex. pour le cours d'intégration. Avec un faible revenu, vous pouvez demander une dispense.","nl":"Het deel dat u zelf betaalt, bijv. voor de integratiecursus. Met een laag inkomen kunt u vrijstelling aanvragen.","ro":"Partea pe care o plătiți singur, de ex. pentru cursul de integrare. Cu venit mic puteți cere scutire.","es":"La parte que pagas tú, p. ej. del curso de integración. Con ingresos bajos puedes pedir la exención.","ku":"Beşa ku tu bi xwe didî, mînak ji bo kursa entegrasyonê. Bi dahata kêm dikarî azadkirinê bixwazî."},"x":"Für die Teilnahme am Integrationskurs ist ein Kostenbeitrag zu leisten.","l":"bm2"},
{"w":"Kindergeld","a":"das","c":"geld","g":{"tr":"çocuk parası","bg":"детски надбавки","ar":"إعانة الأطفال","uk":"допомога на дітей","pl":"zasiłek na dziecko","en":"child benefit","el":"επίδομα τέκνων","fr":"allocations familiales","nl":"kinderbijslag","ro":"alocație pentru copii","es":"prestación por hijos","ku":"pereyê zarokan"},"d":{"de":"Monatliches Geld für Kinder, das Eltern bei der Familienkasse beantragen. Dafür brauchen Sie die Steuer-ID von Kind und Eltern.","tr":"Çocuklar için Familienkasse'ye başvurularak alınan aylık para. Çocuğun ve ebeveynlerin vergi numarası gerekir.","bg":"Месечни пари за деца, които се искат от Familienkasse. Нужни са данъчните номера на детето и родителите.","ar":"مال شهري للأطفال يُطلب من Familienkasse. تحتاج الرقم الضريبي للطفل والوالدين.","uk":"Щомісячні гроші на дітей, які просять у Familienkasse. Потрібні податкові номери дитини й батьків.","pl":"Comiesięczne pieniądze na dzieci, o które wnioskuje się w Familienkasse. Potrzebne są numery podatkowe dziecka i rodziców.","en":"Monthly money for children, applied for at the Familienkasse. You need the tax IDs of the child and the parents.","el":"Μηνιαία χρήματα για παιδιά, με αίτηση στη Familienkasse. Χρειάζονται οι φορολογικοί αριθμοί παιδιού και γονέων.","fr":"Argent mensuel pour les enfants, à demander à la Familienkasse. Il faut les numéros fiscaux de l'enfant et des parents.","nl":"Maandelijks geld voor kinderen, aan te vragen bij de Familienkasse. U hebt de belastingnummers van kind en ouders nodig.","ro":"Bani lunari pentru copii, ceruți la Familienkasse. Sunt necesare codurile fiscale ale copilului și părinților.","es":"Dinero mensual por hijos, que se pide a la Familienkasse. Se necesitan los números fiscales del hijo y de los padres.","ku":"Pereyê mehane ji bo zarokan ku ji Familienkasse tê xwestin. Hejmarên bacê yên zarok û dêûbavan pêwîst in."},"x":"Der Kindergeldantrag ist bei der Familienkasse einzureichen."},
{"w":"Wohngeld","a":"das","c":"geld","g":{"tr":"kira yardımı","bg":"помощ за наем","ar":"إعانة السكن","uk":"житлова субсидія","pl":"dodatek mieszkaniowy","en":"housing benefit","el":"επίδομα στέγασης","fr":"aide au logement","nl":"huurtoeslag","ro":"ajutor pentru locuință","es":"ayuda a la vivienda","ku":"alîkariya kirê"},"d":{"de":"Ein Zuschuss zur Miete für Menschen mit kleinem Einkommen. Es wird ab dem Monat des Antrags gezahlt, nicht rückwirkend.","tr":"Az gelirli kişilere kira için verilen destek. Başvuru ayından itibaren ödenir, geriye dönük değil.","bg":"Помощ за наема при нисък доход. Плаща се от месеца на заявлението, не със задна дата.","ar":"دعم للإيجار لأصحاب الدخل المنخفض. يُدفع من شهر الطلب وليس بأثر رجعي.","uk":"Допомога на оренду для людей з малим доходом. Виплачується з місяця заяви, не заднім числом.","pl":"Dopłata do czynszu dla osób o niskich dochodach. Wypłacana od miesiąca wniosku, nie wstecz.","en":"A rent subsidy for people on a low income. Paid from the month of application, not retroactively.","el":"Επιδότηση ενοικίου για άτομα με χαμηλό εισόδημα. Πληρώνεται από τον μήνα της αίτησης, όχι αναδρομικά.","fr":"Une aide au loyer pour les personnes à faible revenu. Versée à partir du mois de la demande, pas rétroactivement.","nl":"Een bijdrage in de huur voor mensen met een laag inkomen. Betaald vanaf de maand van aanvraag, niet met terugwerkende kracht.","ro":"Sprijin pentru chirie pentru persoane cu venit mic. Se plătește din luna cererii, nu retroactiv.","es":"Una ayuda para el alquiler para personas con ingresos bajos. Se paga desde el mes de la solicitud, no con efecto retroactivo.","ku":"Alîkariya kirê ji bo kesên bi dahata kêm. Ji meha serlêdanê tê dayîn, ne paşverû."},"x":"Wohngeld wird vom Ersten des Monats an bewilligt, in dem der Antrag gestellt wurde."},
{"w":"Anmeldung","a":"die","c":"wohn","g":{"tr":"adres kaydı","bg":"адресна регистрация","ar":"تسجيل العنوان","uk":"реєстрація адреси","pl":"zameldowanie","en":"address registration","el":"δήλωση διεύθυνσης","fr":"déclaration de domicile","nl":"adresinschrijving","ro":"înregistrarea domiciliului","es":"empadronamiento","ku":"qeyda navnîşanê"},"d":{"de":"Nach einem Umzug müssen Sie sich innerhalb von 2 Wochen beim Bürgeramt mit Ihrer neuen Adresse melden.","tr":"Taşındıktan sonra 2 hafta içinde yeni adresinizi Bürgeramt'a bildirmeniz gerekir.","bg":"След преместване трябва да регистрирате новия си адрес в Bürgeramt до 2 седмици.","ar":"بعد الانتقال يجب تسجيل عنوانك الجديد في Bürgeramt خلال أسبوعين.","uk":"Після переїзду треба зареєструвати нову адресу в Bürgeramt протягом 2 тижнів.","pl":"Po przeprowadzce musisz zameldować nowy adres w Bürgeramt w ciągu 2 tygodni.","en":"After moving you must register your new address at the Bürgeramt within 2 weeks.","el":"Μετά από μετακόμιση πρέπει να δηλώσετε τη νέα διεύθυνση στο Bürgeramt μέσα σε 2 εβδομάδες.","fr":"Après un déménagement, vous devez déclarer votre nouvelle adresse au Bürgeramt dans les 2 semaines.","nl":"Na een verhuizing moet u uw nieuwe adres binnen 2 weken bij het Bürgeramt inschrijven.","ro":"După mutare trebuie să vă înregistrați noua adresă la Bürgeramt în 2 săptămâni.","es":"Tras una mudanza debes empadronarte con tu nueva dirección en el Bürgeramt en 2 semanas.","ku":"Piştî barkirinê divê tu di nav 2 hefteyan de navnîşana xwe ya nû li Bürgeramt qeyd bikî."},"x":"Bitte bringen Sie zur Anmeldung Ihren Pass und die Wohnungsgeberbestätigung mit.","l":"r2","f":true},
{"w":"Meldebescheinigung","a":"die","c":"wohn","g":{"tr":"ikamet belgesi","bg":"удостоверение за регистрация","ar":"شهادة تسجيل السكن","uk":"довідка про реєстрацію","pl":"zaświadczenie o zameldowaniu","en":"proof of registration","el":"βεβαίωση κατοικίας","fr":"attestation de domicile","nl":"bewijs van inschrijving","ro":"adeverință de domiciliu","es":"certificado de empadronamiento","ku":"belgeya qeydê"},"d":{"de":"Ein Papier vom Bürgeramt, das zeigt, wo Sie gemeldet sind. Banken, Arbeitgeber oder Ämter fragen oft danach.","tr":"Bürgeramt'tan nerede kayıtlı olduğunuzu gösteren belge. Banka, işveren veya daireler sık ister.","bg":"Документ от Bürgeramt, който показва къде сте регистрирани. Банки, работодатели и служби често го искат.","ar":"ورقة من Bürgeramt تُظهر مكان تسجيلك. تطلبها البنوك وأصحاب العمل والدوائر كثيراً.","uk":"Документ від Bürgeramt про те, де ви зареєстровані. Його часто просять банки, роботодавці й установи.","pl":"Dokument z Bürgeramt pokazujący, gdzie jesteś zameldowany. Często chcą go banki, pracodawcy i urzędy.","en":"A paper from the Bürgeramt showing where you are registered. Banks, employers and offices often ask for it.","el":"Έγγραφο από το Bürgeramt που δείχνει πού είστε δηλωμένοι. Τράπεζες, εργοδότες και υπηρεσίες το ζητούν συχνά.","fr":"Un papier du Bürgeramt qui montre où vous êtes déclaré. Banques, employeurs et administrations le demandent souvent.","nl":"Een papier van het Bürgeramt dat laat zien waar u staat ingeschreven. Banken, werkgevers en instanties vragen er vaak om.","ro":"Un act de la Bürgeramt care arată unde sunteți înregistrat. Băncile, angajatorii și autoritățile îl cer des.","es":"Un papel del Bürgeramt que muestra dónde estás empadronado. Bancos, empleadores y oficinas lo piden a menudo.","ku":"Belgeyek ji Bürgeramt ku nîşan dide tu li ku qeydkirî yî. Bank, kardêr û dezgeh gelek caran dixwazin."},"x":"Bitte legen Sie eine aktuelle Meldebescheinigung vor.","l":"r1"},
{"w":"Wohnungsgeberbestätigung","a":"die","c":"wohn","g":{"tr":"ev sahibi onayı","bg":"потвърждение от наемодателя","ar":"تأكيد المؤجر","uk":"підтвердження орендодавця","pl":"potwierdzenie wynajmującego","en":"landlord's confirmation","el":"βεβαίωση ιδιοκτήτη","fr":"attestation du propriétaire","nl":"verklaring verhuurder","ro":"confirmarea proprietarului","es":"confirmación del arrendador","ku":"pejirandina xwedîxanî"},"d":{"de":"Die Bestätigung Ihres Vermieters, dass Sie eingezogen sind. Sie brauchen sie für die Anmeldung; der Vermieter muss sie innerhalb von 2 Wochen geben.","tr":"Ev sahibinizin taşındığınızı onaylayan belgesi. Kayıt için gerekir; ev sahibi 2 hafta içinde vermek zorunda.","bg":"Потвърждението на наемодателя, че сте се нанесли. Нужно е за регистрацията; наемодателят трябва да го даде до 2 седмици.","ar":"تأكيد المؤجر أنك سكنت. تحتاجه للتسجيل؛ ويجب على المؤجر تقديمه خلال أسبوعين.","uk":"Підтвердження орендодавця, що ви в'їхали. Потрібне для реєстрації; орендодавець мусить дати його протягом 2 тижнів.","pl":"Potwierdzenie wynajmującego, że się wprowadziłeś. Potrzebne do zameldowania; wynajmujący musi je dać w ciągu 2 tygodni.","en":"Your landlord's confirmation that you moved in. You need it to register; the landlord must give it within 2 weeks.","el":"Η βεβαίωση του ιδιοκτήτη ότι μετακομίσατε. Τη χρειάζεστε για τη δήλωση· ο ιδιοκτήτης πρέπει να τη δώσει μέσα σε 2 εβδομάδες.","fr":"La confirmation de votre propriétaire que vous avez emménagé. Nécessaire pour la déclaration ; il doit la donner dans les 2 semaines.","nl":"De bevestiging van uw verhuurder dat u er bent komen wonen. Nodig voor de inschrijving; de verhuurder moet die binnen 2 weken geven.","ro":"Confirmarea proprietarului că v-ați mutat. Necesară pentru înregistrare; proprietarul trebuie să o dea în 2 săptămâni.","es":"La confirmación de tu arrendador de que te mudaste. La necesitas para empadronarte; debe dártela en 2 semanas.","ku":"Pejirandina xwedîxanî ku tu bi cih bûyî. Ji bo qeydê pêwîst e; xwedîxanî divê di nav 2 hefteyan de bide."},"x":"Für die Anmeldung fehlt noch die Wohnungsgeberbestätigung.","l":"r5"},
{"w":"Abmeldung","a":"die","c":"wohn","g":{"tr":"kayıt silme","bg":"отписване","ar":"إلغاء التسجيل","uk":"зняття з реєстрації","pl":"wymeldowanie","en":"deregistration","el":"διαγραφή","fr":"radiation","nl":"uitschrijving","ro":"radiere","es":"baja del padrón","ku":"rakirina qeydê"},"d":{"de":"Wenn Sie ins Ausland ziehen, melden Sie Ihre Wohnung beim Bürgeramt ab – innerhalb von 2 Wochen nach dem Auszug.","tr":"Yurt dışına taşınırsanız, çıkıştan sonra 2 hafta içinde Bürgeramt'ta kaydınızı sildirirsiniz.","bg":"Ако се местите в чужбина, се отписвате в Bürgeramt до 2 седмици след изнасянето.","ar":"إذا انتقلت إلى الخارج تلغي تسجيلك في Bürgeramt خلال أسبوعين بعد المغادرة.","uk":"Якщо ви переїжджаєте за кордон, знімаєтеся з реєстрації в Bürgeramt протягом 2 тижнів після виїзду.","pl":"Jeśli przeprowadzasz się za granicę, wymeldowujesz się w Bürgeramt w ciągu 2 tygodni po wyprowadzce.","en":"If you move abroad, you deregister at the Bürgeramt within 2 weeks after moving out.","el":"Αν μετακομίσετε στο εξωτερικό, διαγράφεστε στο Bürgeramt μέσα σε 2 εβδομάδες από την αποχώρηση.","fr":"Si vous partez à l'étranger, vous vous radiez au Bürgeramt dans les 2 semaines après le départ.","nl":"Verhuist u naar het buitenland, dan schrijft u zich binnen 2 weken na vertrek uit bij het Bürgeramt.","ro":"Dacă vă mutați în străinătate, vă radiați la Bürgeramt în 2 săptămâni după plecare.","es":"Si te mudas al extranjero, te das de baja en el Bürgeramt en las 2 semanas siguientes a la salida.","ku":"Heke tu diçî derveyî welat, di nav 2 hefteyan de piştî derketinê qeyda xwe li Bürgeramt radikî."},"x":"Die Abmeldung ist innerhalb von zwei Wochen nach dem Auszug vorzunehmen.","l":"r4","f":true},
{"w":"Nebenkostenabrechnung","a":"die","c":"wohn","g":{"tr":"yan gider hesabı","bg":"сметка за режийни","ar":"فاتورة التكاليف الجانبية","uk":"розрахунок комунальних","pl":"rozliczenie kosztów dodatkowych","en":"utility bill","el":"εκκαθάριση κοινοχρήστων","fr":"décompte des charges","nl":"servicekostenafrekening","ro":"decont utilități","es":"liquidación de gastos","ku":"hesabê lêçûnên alî"},"d":{"de":"Die jährliche Rechnung für Heizung, Wasser, Müll usw. Sie haben 12 Monate Zeit für Einwände und dürfen die Belege ansehen.","tr":"Isınma, su, çöp vb. için yıllık hesap. İtiraz için 12 ayınız var ve faturaları görebilirsiniz.","bg":"Годишната сметка за отопление, вода, смет и др. Имате 12 месеца за възражения и можете да видите разписките.","ar":"الفاتورة السنوية للتدفئة والماء والقمامة وغيرها. لديك 12 شهراً للاعتراض ويمكنك رؤية الإيصالات.","uk":"Щорічний рахунок за опалення, воду, сміття тощо. Маєте 12 місяців на заперечення й можете побачити квитанції.","pl":"Roczny rachunek za ogrzewanie, wodę, śmieci itd. Masz 12 miesięcy na zastrzeżenia i możesz obejrzeć rachunki.","en":"The yearly bill for heating, water, rubbish etc. You have 12 months to object and may see the receipts.","el":"Ο ετήσιος λογαριασμός για θέρμανση, νερό, σκουπίδια κ.λπ. Έχετε 12 μήνες για αντιρρήσεις και μπορείτε να δείτε τα παραστατικά.","fr":"La facture annuelle de chauffage, eau, ordures, etc. Vous avez 12 mois pour contester et pouvez voir les justificatifs.","nl":"De jaarlijkse rekening voor verwarming, water, afval enz. U hebt 12 maanden voor bezwaren en mag de bonnen inzien.","ro":"Factura anuală pentru încălzire, apă, gunoi etc. Aveți 12 luni pentru obiecții și puteți vedea documentele.","es":"La factura anual de calefacción, agua, basura, etc. Tienes 12 meses para objetar y puedes ver los justificantes.","ku":"Hesabê salane ji bo germkirin, av, gemar û hwd. 12 mehên te hene ji bo îtîrazê û dikarî belgeyan bibînî."},"x":"Aus der Nebenkostenabrechnung ergibt sich eine Nachzahlung von 180,00 €.","f":true},
{"w":"Kaution","a":"die","c":"wohn","g":{"tr":"depozito","bg":"депозит","ar":"تأمين الإيجار","uk":"застава","pl":"kaucja","en":"deposit","el":"εγγύηση ενοικίου","fr":"dépôt de garantie","nl":"waarborgsom","ro":"garanție","es":"fianza","ku":"depozîto"},"d":{"de":"Geld, das Sie dem Vermieter als Sicherheit geben. Höchstens 3 Monatsmieten ohne Nebenkosten; nach dem Auszug bekommen Sie sie zurück.","tr":"Ev sahibine güvence olarak verdiğiniz para. En fazla yan giderler hariç 3 aylık kira; taşınınca geri alırsınız.","bg":"Пари, които давате на наемодателя като гаранция. Най-много 3 наема без режийни; връщат ви ги след изнасяне.","ar":"مال تعطيه للمؤجر ضماناً. حدّه الأقصى 3 أشهر إيجار دون التكاليف الجانبية؛ تستعيده بعد المغادرة.","uk":"Гроші, які ви даєте орендодавцю як гарантію. Не більше 3 місячних оренд без комунальних; після виїзду їх повертають.","pl":"Pieniądze, które dajesz wynajmującemu jako zabezpieczenie. Maksymalnie 3 czynsze bez opłat; po wyprowadzce je odzyskujesz.","en":"Money you give the landlord as security. At most 3 months' rent without utilities; you get it back after moving out.","el":"Χρήματα που δίνετε στον ιδιοκτήτη ως εγγύηση. Το πολύ 3 ενοίκια χωρίς κοινόχρηστα· τα παίρνετε πίσω μετά την αποχώρηση.","fr":"L'argent versé au propriétaire en garantie. 3 mois de loyer hors charges au maximum ; restitué après le départ.","nl":"Geld dat u de verhuurder als zekerheid geeft. Hoogstens 3 maanden kale huur; na vertrek krijgt u het terug.","ro":"Bani pe care îi dați proprietarului ca garanție. Cel mult 3 chirii fără utilități; îi primiți înapoi după plecare.","es":"Dinero que das al arrendador como garantía. Como máximo 3 mensualidades sin gastos; te lo devuelven al irte.","ku":"Pereyê ku wek ewlehî didî xwedîxanî. Herî zêde 3 kirêyên bê lêçûnên alî; piştî derketinê vedigere."},"x":"Die Kaution in Höhe von drei Nettokaltmieten ist zu Beginn des Mietverhältnisses fällig."},
{"w":"Aufenthaltstitel","a":"der","c":"aufenth","g":{"tr":"oturum izni","bg":"разрешение за пребиваване","ar":"إذن إقامة","uk":"дозвіл на проживання","pl":"dokument pobytowy","en":"residence permit","el":"άδεια διαμονής","fr":"titre de séjour","nl":"verblijfsvergunning","ro":"permis de ședere","es":"permiso de residencia","ku":"destûra mayînê"},"d":{"de":"Die Erlaubnis, in Deutschland zu leben, z. B. Aufenthaltserlaubnis oder Niederlassungserlaubnis. Beantragen Sie die Verlängerung vor dem Ablauf.","tr":"Almanya'da yaşama izni, örneğin oturum izni veya süresiz oturum. Uzatmayı süre bitmeden isteyin.","bg":"Разрешението да живеете в Германия, напр. разрешение за пребиваване или установяване. Искайте удължаване преди изтичане.","ar":"إذن العيش في ألمانيا، مثل إذن الإقامة أو الإقامة الدائمة. اطلب التمديد قبل انتهاء الصلاحية.","uk":"Дозвіл жити в Німеччині, напр. дозвіл на проживання чи поселення. Продовження просіть до закінчення строку.","pl":"Pozwolenie na życie w Niemczech, np. zezwolenie na pobyt lub osiedlenie się. O przedłużenie wnioskuj przed upływem ważności.","en":"Permission to live in Germany, e.g. a residence or settlement permit. Apply for the extension before it expires.","el":"Η άδεια να ζείτε στη Γερμανία, π.χ. άδεια διαμονής ή εγκατάστασης. Ζητήστε παράταση πριν λήξει.","fr":"L'autorisation de vivre en Allemagne, p. ex. titre de séjour ou permis d'établissement. Demandez la prolongation avant l'expiration.","nl":"De toestemming om in Duitsland te wonen, bijv. verblijfs- of vestigingsvergunning. Vraag verlenging aan vóór de vervaldatum.","ro":"Permisiunea de a locui în Germania, de ex. permis de ședere sau de stabilire. Cereți prelungirea înainte să expire.","es":"El permiso para vivir en Alemania, p. ej. de residencia o de establecimiento. Pide la prórroga antes de que caduque.","ku":"Destûra jiyanê li Almanyayê, wek destûra mayînê an rûniştina mayînde. Berî ku biqede dirêjkirinê bixwaze."},"x":"Ihr Aufenthaltstitel ist gültig bis zum 30.06.","l":"b1","f":true},
{"w":"Fiktionsbescheinigung","a":"die","c":"aufenth","g":{"tr":"geçici oturum belgesi","bg":"временно удостоверение","ar":"شهادة إقامة مؤقتة","uk":"тимчасова довідка","pl":"zaświadczenie tymczasowe","en":"interim residence certificate","el":"προσωρινή βεβαίωση","fr":"attestation provisoire","nl":"tijdelijke verklaring","ro":"adeverință provizorie","es":"certificado provisional","ku":"belgeya demkî"},"d":{"de":"Ein Papier der Ausländerbehörde: Ihr Aufenthalt gilt weiter, solange über Ihren rechtzeitigen Antrag noch nicht entschieden ist.","tr":"Yabancılar dairesinin belgesi: zamanında yaptığınız başvuru karara bağlanana kadar oturumunuz geçerli sayılır.","bg":"Документ от службата за чужденци: пребиваването ви важи, докато навременното ви заявление не е решено.","ar":"ورقة من دائرة الأجانب: تبقى إقامتك سارية ما دام طلبك المقدَّم في وقته لم يُبتّ فيه.","uk":"Документ відомства у справах іноземців: ваше перебування діє, поки вашу вчасно подану заяву не вирішено.","pl":"Dokument urzędu ds. cudzoziemców: twój pobyt jest ważny, dopóki nie rozpatrzono wniosku złożonego na czas.","en":"A paper from the immigration office: your stay remains valid while your timely application has not been decided.","el":"Έγγραφο της υπηρεσίας αλλοδαπών: η διαμονή σας ισχύει όσο δεν έχει αποφασιστεί η έγκαιρη αίτησή σας.","fr":"Un document du service des étrangers : votre séjour reste valable tant que votre demande déposée à temps n'est pas tranchée.","nl":"Een papier van de vreemdelingendienst: uw verblijf blijft geldig zolang uw tijdige aanvraag niet is beslist.","ro":"Un act al biroului pentru străini: șederea rămâne valabilă cât timp cererea depusă la timp nu e soluționată.","es":"Un papel de la oficina de extranjería: tu estancia sigue siendo válida mientras no se decida tu solicitud presentada a tiempo.","ku":"Belgeyek ji dezgeha biyaniyan: mayîna te derbasdar e heta ku li ser serlêdana te ya di wextê xwe de biryar neyê dayîn."},"x":"Bis zur Entscheidung über Ihren Antrag erhalten Sie eine Fiktionsbescheinigung.","l":"b1"},
{"w":"Duldung","a":"die","c":"aufenth","g":{"tr":"hoşgörü belgesi (Duldung)","bg":"толериране (Duldung)","ar":"تسامح (Duldung)","uk":"толерування (Duldung)","pl":"tolerowanie (Duldung)","en":"toleration (Duldung)","el":"ανοχή (Duldung)","fr":"tolérance (Duldung)","nl":"gedoogstatus (Duldung)","ro":"tolerare (Duldung)","es":"tolerancia (Duldung)","ku":"tehemul (Duldung)"},"d":{"de":"Keine Aufenthaltserlaubnis, sondern eine Bescheinigung, dass die Abschiebung vorübergehend ausgesetzt ist.","tr":"Oturum izni değil; sınır dışı etmenin geçici olarak ertelendiğini gösteren belge.","bg":"Не е разрешение за пребиваване, а удостоверение, че депортирането временно е спряно.","ar":"ليست إذن إقامة، بل شهادة بأن الترحيل معلّق مؤقتاً.","uk":"Не дозвіл на проживання, а довідка, що депортацію тимчасово призупинено.","pl":"Nie zezwolenie na pobyt, lecz zaświadczenie, że deportację tymczasowo wstrzymano.","en":"Not a residence permit, but a certificate that deportation is temporarily suspended.","el":"Δεν είναι άδεια διαμονής, αλλά βεβαίωση ότι η απέλαση έχει ανασταλεί προσωρινά.","fr":"Pas un titre de séjour, mais une attestation que l'expulsion est suspendue temporairement.","nl":"Geen verblijfsvergunning, maar een verklaring dat uitzetting tijdelijk is opgeschort.","ro":"Nu este permis de ședere, ci o adeverință că expulzarea este suspendată temporar.","es":"No es un permiso de residencia, sino un certificado de que la deportación está suspendida temporalmente.","ku":"Ne destûra mayînê ye, belgeyek e ku dersînorkirin bi awayekî demkî hatiye rawestandin."},"x":"Die Abschiebung wird vorübergehend ausgesetzt (Duldung)."},
{"w":"Niederlassungserlaubnis","a":"die","c":"aufenth","g":{"tr":"süresiz oturum izni","bg":"разрешение за установяване","ar":"إقامة دائمة","uk":"дозвіл на поселення","pl":"zezwolenie na osiedlenie się","en":"settlement permit","el":"άδεια εγκατάστασης","fr":"permis d'établissement","nl":"vestigingsvergunning","ro":"permis de stabilire","es":"permiso de establecimiento","ku":"destûra rûniştina mayînde"},"d":{"de":"Ein unbefristeter Aufenthaltstitel. Sie müssen ihn nicht mehr verlängern; nur die Karte selbst hat ein Ablaufdatum.","tr":"Süresiz oturum izni. Artık uzatmanız gerekmez; sadece kartın kendisinin bitiş tarihi vardır.","bg":"Безсрочно разрешение за пребиваване. Не трябва да го удължавате; само картата има срок на валидност.","ar":"إذن إقامة غير محدود المدة. لا تحتاج إلى تمديده؛ فقط البطاقة نفسها لها تاريخ انتهاء.","uk":"Безстроковий дозвіл на проживання. Продовжувати не треба; строк дії має лише сама картка.","pl":"Bezterminowe zezwolenie na pobyt. Nie trzeba go przedłużać; datę ważności ma tylko sama karta.","en":"A permanent residence permit. You no longer need to extend it; only the card itself has an expiry date.","el":"Αόριστης διάρκειας άδεια διαμονής. Δεν χρειάζεται παράταση· μόνο η κάρτα έχει ημερομηνία λήξης.","fr":"Un titre de séjour illimité. Plus besoin de le prolonger ; seule la carte a une date d'expiration.","nl":"Een onbeperkte verblijfsvergunning. Verlengen hoeft niet meer; alleen de pas zelf heeft een vervaldatum.","ro":"Un permis de ședere pe durată nelimitată. Nu mai trebuie prelungit; doar cardul are dată de expirare.","es":"Un permiso de residencia indefinido. Ya no hay que prorrogarlo; solo la tarjeta tiene fecha de caducidad.","ku":"Destûra mayînê ya bê sînor. Êdî ne hewce ye dirêj bikî; tenê kart bi xwe dîroka dawiyê heye."},"x":"Ihnen wird eine Niederlassungserlaubnis erteilt."},
{"w":"Ausländerbehörde","a":"die","c":"aufenth","g":{"tr":"yabancılar dairesi","bg":"служба за чужденци","ar":"دائرة الأجانب","uk":"відомство у справах іноземців","pl":"urząd ds. cudzoziemców","en":"immigration office","el":"υπηρεσία αλλοδαπών","fr":"service des étrangers","nl":"vreemdelingendienst","ro":"biroul pentru străini","es":"oficina de extranjería","ku":"dezgeha biyaniyan"},"d":{"de":"Das Amt für Visum, Aufenthaltstitel und Arbeitserlaubnis von Ausländern. Zuständig ist die Behörde an Ihrem Wohnort.","tr":"Yabancıların vize, oturum ve çalışma izni işlerine bakan daire. Oturduğunuz yerdeki daire yetkilidir.","bg":"Службата за визи, пребиваване и разрешения за работа на чужденци. Компетентна е тази по местоживеене.","ar":"الدائرة المختصة بالتأشيرات والإقامات وتصاريح العمل للأجانب. المختصة هي دائرة مكان سكنك.","uk":"Установа, що займається візами, дозволами на проживання й роботу для іноземців. Компетентна установа за місцем проживання.","pl":"Urząd od wiz, zezwoleń na pobyt i pracę dla cudzoziemców. Właściwy jest urząd w miejscu zamieszkania.","en":"The office for visas, residence and work permits of foreigners. The office where you live is responsible.","el":"Η υπηρεσία για βίζες, άδειες διαμονής και εργασίας αλλοδαπών. Αρμόδια είναι αυτή του τόπου κατοικίας σας.","fr":"L'administration chargée des visas, titres de séjour et permis de travail des étrangers. Compétente : celle de votre lieu de résidence.","nl":"De instantie voor visa, verblijfs- en werkvergunningen van buitenlanders. Bevoegd is die van uw woonplaats.","ro":"Autoritatea pentru vize, permise de ședere și de muncă ale străinilor. Competentă este cea de la domiciliu.","es":"La oficina de visados, permisos de residencia y de trabajo de los extranjeros. Es competente la de tu lugar de residencia.","ku":"Dezgeha ji bo vîze, destûra mayînê û karkirinê ya biyaniyan. Ya li cihê ku tu lê dijî berpirsiyar e."},"x":"Bitte vereinbaren Sie einen Termin bei der Ausländerbehörde.","l":"b4"},
{"w":"Krankenkasse","a":"die","c":"gesund","g":{"tr":"sağlık kasası","bg":"здравна каса","ar":"صندوق التأمين الصحي","uk":"лікарняна каса","pl":"kasa chorych","en":"health insurer","el":"ασφαλιστικό ταμείο υγείας","fr":"caisse d'assurance maladie","nl":"zorgverzekeraar","ro":"casa de asigurări de sănătate","es":"aseguradora médica","ku":"sîgorteya tenduristiyê"},"d":{"de":"Ihre Krankenversicherung. In Deutschland muss jeder krankenversichert sein; die Kasse zahlt Arzt, Klinik und viele Medikamente.","tr":"Sağlık sigortanız. Almanya'da herkesin sigortalı olması gerekir; kasa doktoru, hastaneyi ve birçok ilacı öder.","bg":"Здравната ви осигуровка. В Германия всеки трябва да е осигурен; касата плаща лекар, болница и много лекарства.","ar":"تأمينك الصحي. يجب أن يكون كل شخص في ألمانيا مؤمَّناً؛ الصندوق يدفع للطبيب والمستشفى وكثير من الأدوية.","uk":"Ваше медичне страхування. У Німеччині кожен мусить бути застрахований; каса платить за лікаря, лікарню й багато ліків.","pl":"Twoje ubezpieczenie zdrowotne. W Niemczech każdy musi być ubezpieczony; kasa płaci za lekarza, szpital i wiele leków.","en":"Your health insurance. Everyone in Germany must be insured; the insurer pays for doctors, hospital and many medicines.","el":"Η ασφάλιση υγείας σας. Στη Γερμανία όλοι πρέπει να είναι ασφαλισμένοι· το ταμείο πληρώνει γιατρό, νοσοκομείο και πολλά φάρμακα.","fr":"Votre assurance maladie. En Allemagne, tout le monde doit être assuré ; la caisse paie médecin, hôpital et de nombreux médicaments.","nl":"Uw zorgverzekering. In Duitsland moet iedereen verzekerd zijn; de verzekeraar betaalt arts, ziekenhuis en veel medicijnen.","ro":"Asigurarea de sănătate. În Germania toți trebuie să fie asigurați; casa plătește medicul, spitalul și multe medicamente.","es":"Tu seguro médico. En Alemania todos deben estar asegurados; la aseguradora paga médico, hospital y muchos medicamentos.","ku":"Sîgorteya te ya tenduristiyê. Li Almanyayê divê her kes sîgortekirî be; sîgorte bijîşk, nexweşxane û gelek dermanan dide."},"x":"Bitte teilen Sie uns mit, bei welcher Krankenkasse Sie versichert sind."},
{"w":"Familienversicherung","a":"die","c":"gesund","g":{"tr":"aile sigortası","bg":"семейно осигуряване","ar":"التأمين العائلي","uk":"сімейне страхування","pl":"ubezpieczenie rodzinne","en":"family insurance","el":"οικογενειακή ασφάλιση","fr":"assurance familiale","nl":"gezinsverzekering","ro":"asigurare de familie","es":"seguro familiar","ku":"sîgorteya malbatê"},"d":{"de":"Ehepartner und Kinder ohne eigenes oder mit sehr kleinem Einkommen können bei Ihrer gesetzlichen Krankenkasse kostenlos mitversichert sein.","tr":"Geliri olmayan ya da çok az olan eş ve çocuklar yasal sağlık kasanızda ücretsiz sigortalı olabilir.","bg":"Съпруг и деца без или с много малък доход могат да бъдат осигурени безплатно в държавната ви здравна каса.","ar":"الزوج والأطفال بلا دخل أو بدخل قليل جداً يمكن تأمينهم مجاناً في صندوقك الصحي القانوني.","uk":"Чоловік/дружина й діти без доходу або з дуже малим доходом можуть бути безкоштовно застраховані у вашій державній касі.","pl":"Małżonek i dzieci bez dochodu lub z bardzo małym dochodem mogą być bezpłatnie ubezpieczeni w twojej ustawowej kasie chorych.","en":"A spouse and children with no or very little income can be insured free with your statutory health insurer.","el":"Σύζυγος και παιδιά χωρίς ή με πολύ μικρό εισόδημα μπορούν να ασφαλιστούν δωρεάν στο δημόσιο ταμείο σας.","fr":"Le conjoint et les enfants sans revenu ou avec un très faible revenu peuvent être assurés gratuitement dans votre caisse légale.","nl":"Echtgeno(o)t(e) en kinderen zonder of met heel weinig inkomen kunnen gratis meeverzekerd zijn bij uw wettelijke verzekeraar.","ro":"Soțul/soția și copiii fără venit sau cu venit foarte mic pot fi asigurați gratuit la casa dumneavoastră legală.","es":"El cónyuge y los hijos sin ingresos o con ingresos muy bajos pueden estar asegurados gratis en tu seguro público.","ku":"Hevjîn û zarokên bê dahat an bi dahateke pir kêm dikarin di sîgorteya te ya qanûnî de belaş werin sîgortekirin."},"x":"Für Ihren Ehepartner ist eine Familienversicherung möglich.","l":"k1"},
{"w":"Zuzahlungsbefreiung","a":"die","c":"gesund","g":{"tr":"katkı payı muafiyeti","bg":"освобождаване от доплащания","ar":"الإعفاء من المساهمات","uk":"звільнення від доплат","pl":"zwolnienie z dopłat","en":"exemption from co-payments","el":"απαλλαγή από συμμετοχές","fr":"dispense de participation","nl":"vrijstelling eigen bijdragen","ro":"scutire de coplăți","es":"exención de copagos","ku":"azadkirina ji beşdariyê"},"d":{"de":"Wenn Ihre Zuzahlungen im Jahr 2 % Ihres Bruttoeinkommens übersteigen (chronisch krank: 1 %), befreit die Krankenkasse Sie. Belege sammeln!","tr":"Yıllık katkı paylarınız brüt gelirinizin %2'sini (kronik hastaysanız %1'ini) aşarsa kasa sizi muaf tutar. Fişleri saklayın!","bg":"Ако доплащанията за година надхвърлят 2% от брутния ви доход (при хронично болни: 1%), касата ви освобождава. Пазете бележките!","ar":"إذا تجاوزت مساهماتك في السنة 2% من دخلك الإجمالي (للمرضى المزمنين 1%) يعفيك الصندوق. احتفظ بالإيصالات!","uk":"Якщо доплати за рік перевищують 2% вашого валового доходу (хронічно хворим 1%), каса вас звільняє. Зберігайте чеки!","pl":"Jeśli dopłaty w roku przekroczą 2% twojego dochodu brutto (przewlekle chorzy: 1%), kasa cię zwalnia. Zbieraj paragony!","en":"If your co-payments in a year exceed 2% of your gross income (chronically ill: 1%), the insurer exempts you. Keep receipts!","el":"Αν οι συμμετοχές σας σε ένα έτος ξεπεράσουν το 2% του ακαθάριστου εισοδήματος (χρόνια πάσχοντες: 1%), το ταμείο σας απαλλάσσει. Κρατήστε αποδείξεις!","fr":"Si vos participations annuelles dépassent 2 % de votre revenu brut (malades chroniques : 1 %), la caisse vous dispense. Gardez les reçus !","nl":"Zijn uw eigen bijdragen in een jaar hoger dan 2% van uw bruto-inkomen (chronisch zieken: 1%), dan stelt de verzekeraar u vrij. Bewaar bonnetjes!","ro":"Dacă coplățile pe un an depășesc 2% din venitul brut (bolnavi cronici: 1%), casa vă scutește. Păstrați bonurile!","es":"Si tus copagos del año superan el 2 % de tus ingresos brutos (enfermos crónicos: 1 %), la aseguradora te exime. ¡Guarda los recibos!","ku":"Heke beşdariyên te di salekê de ji %2ê dahata te ya gelemperî derbas bibin (nexweşên kronîk: %1), sîgorte te azad dike. Fîşan biparêze!"},"x":"Für das Jahr 2026 erhalten Sie eine Zuzahlungsbefreiung.","l":"k4"},
{"w":"Arbeitsunfähigkeitsbescheinigung","a":"die","c":"gesund","g":{"tr":"hastalık raporu","bg":"болничен лист","ar":"شهادة مرضية","uk":"лікарняний","pl":"zwolnienie lekarskie","en":"sick note","el":"βεβαίωση ασθενείας","fr":"arrêt maladie","nl":"ziekmelding van de arts","ro":"concediu medical","es":"baja médica","ku":"rapora nexweşiyê"},"d":{"de":"Die Krankschreibung vom Arzt. Meist schickt die Praxis sie digital an die Krankenkasse; Ihrem Arbeitgeber müssen Sie trotzdem sofort Bescheid sagen.","tr":"Doktordan hastalık raporu. Muayenehane genelde kasaya dijital gönderir; işvereninize yine de hemen haber vermelisiniz.","bg":"Болничният от лекаря. Обикновено практиката го праща цифрово на касата; на работодателя трябва все пак да кажете веднага.","ar":"الإجازة المرضية من الطبيب. غالباً ترسلها العيادة إلكترونياً للصندوق؛ لكن يجب إبلاغ صاحب العمل فوراً.","uk":"Лікарняний від лікаря. Зазвичай практика надсилає його в касу цифрово; роботодавцю все одно треба повідомити одразу.","pl":"Zwolnienie od lekarza. Gabinet zwykle wysyła je cyfrowo do kasy; pracodawcę musisz mimo to od razu powiadomić.","en":"The doctor's sick note. The practice usually sends it digitally to the insurer; you must still tell your employer at once.","el":"Η βεβαίωση ασθενείας του γιατρού. Συνήθως το ιατρείο τη στέλνει ψηφιακά στο ταμείο· τον εργοδότη πρέπει όμως να τον ενημερώσετε αμέσως.","fr":"L'arrêt maladie du médecin. Le cabinet l'envoie en général à la caisse par voie numérique ; prévenez quand même votre employeur tout de suite.","nl":"De ziekmelding van de arts. De praktijk stuurt die meestal digitaal naar de verzekeraar; uw werkgever moet u toch meteen inlichten.","ro":"Concediul medical de la doctor. De obicei cabinetul îl trimite digital casei; angajatorului trebuie totuși să-i spuneți imediat.","es":"La baja del médico. La consulta suele enviarla digitalmente a la aseguradora; aun así debes avisar enseguida a tu empleador.","ku":"Rapora nexweşiyê ji bijîşk. Bi gelemperî klînîk wê bi dîjîtalî dişîne sîgorteyê; lê divê tu yekser ji kardêr re jî bibêjî."},"x":"Bitte reichen Sie für die Zeit ab dem 4. Tag eine Arbeitsunfähigkeitsbescheinigung ein."},
{"w":"Sperrzeit","a":"die","c":"arbeit","g":{"tr":"işsizlik parası kesintisi","bg":"блокиране на помощта","ar":"وقف الإعانة","uk":"блокування допомоги","pl":"okres karencji","en":"benefit suspension","el":"αναστολή επιδόματος","fr":"suspension de l'allocation","nl":"uitkeringsblokkade","ro":"suspendarea ajutorului","es":"suspensión de la prestación","ku":"rawestandina alîkariyê"},"d":{"de":"Eine Zeit ohne Arbeitslosengeld, z. B. wenn Sie selbst gekündigt haben oder sich zu spät arbeitsuchend gemeldet haben. Dagegen ist Widerspruch möglich.","tr":"İşsizlik parası alınmayan dönem, örneğin işi kendiniz bıraktıysanız veya iş arayan kaydını geç yaptıysanız. İtiraz mümkün.","bg":"Период без обезщетение за безработица, напр. ако сами сте напуснали или сте се регистрирали късно. Може да възразите.","ar":"فترة بلا إعانة بطالة، مثلاً إذا استقلت بنفسك أو سجلت كباحث عن عمل متأخراً. يمكنك الاعتراض.","uk":"Період без допомоги з безробіття, напр. якщо ви звільнилися самі або зареєструвалися запізно. Можна заперечити.","pl":"Okres bez zasiłku dla bezrobotnych, np. gdy sam się zwolniłeś lub za późno zarejestrowałeś jako poszukujący pracy. Możliwy sprzeciw.","en":"A period without unemployment benefit, e.g. if you quit yourself or registered as job-seeking too late. You can object.","el":"Περίοδος χωρίς επίδομα ανεργίας, π.χ. αν παραιτηθήκατε ή δηλωθήκατε αργά ως αναζητών εργασία. Μπορείτε να κάνετε ένσταση.","fr":"Une période sans allocation chômage, p. ex. après une démission ou une inscription tardive. Un recours est possible.","nl":"Een periode zonder werkloosheidsuitkering, bijv. na zelf ontslag nemen of te late inschrijving als werkzoekende. Bezwaar is mogelijk.","ro":"O perioadă fără ajutor de șomaj, de ex. dacă v-ați dat demisia sau v-ați înregistrat prea târziu. Contestația e posibilă.","es":"Un periodo sin prestación por desempleo, p. ej. si dimitiste o te inscribiste tarde como demandante de empleo. Puedes recurrir.","ku":"Demeke bê pereyê bêkariyê, mînak heke te bi xwe kar berdabe an dereng wek karger qeyd bûbî. Îtîraz gengaz e."},"x":"Es ist eine Sperrzeit von 12 Wochen eingetreten.","l":"a1","f":true},
{"w":"Arbeitsuchendmeldung","a":"die","c":"arbeit","g":{"tr":"iş arayan olarak kayıt","bg":"регистрация като търсещ работа","ar":"التسجيل كباحث عن عمل","uk":"реєстрація як шукача роботи","pl":"rejestracja jako poszukujący pracy","en":"registering as job-seeker","el":"εγγραφή ως αναζητών εργασία","fr":"inscription comme demandeur d'emploi","nl":"inschrijving als werkzoekende","ro":"înregistrare în căutarea unui loc de muncă","es":"inscripción como demandante de empleo","ku":"qeydkirina wek karger"},"d":{"de":"Sie melden der Agentur für Arbeit, dass Ihre Stelle endet: spätestens 3 Monate vorher, sonst innerhalb von 3 Tagen.","tr":"İşinizin biteceğini Agentur für Arbeit'e bildirirsiniz: en geç 3 ay önce, değilse 3 gün içinde.","bg":"Съобщавате на агенцията по заетостта, че работата ви приключва: поне 3 месеца преди това, иначе до 3 дни.","ar":"تُبلغ وكالة العمل بأن عملك سينتهي: قبل 3 أشهر على الأقل، وإلا خلال 3 أيام.","uk":"Ви повідомляєте агентство праці, що робота закінчується: щонайменше за 3 місяці, інакше протягом 3 днів.","pl":"Informujesz agencję pracy, że twoja praca się kończy: najpóźniej 3 miesiące wcześniej, inaczej w ciągu 3 dni.","en":"You tell the employment agency that your job is ending: at least 3 months before, otherwise within 3 days.","el":"Ενημερώνετε την υπηρεσία απασχόλησης ότι η δουλειά σας τελειώνει: τουλάχιστον 3 μήνες πριν, αλλιώς μέσα σε 3 ημέρες.","fr":"Vous informez l'agence pour l'emploi que votre emploi prend fin : au moins 3 mois avant, sinon dans les 3 jours.","nl":"U meldt het arbeidsbureau dat uw baan eindigt: minstens 3 maanden ervoor, anders binnen 3 dagen.","ro":"Anunțați agenția de ocupare că munca se încheie: cu cel puțin 3 luni înainte, altfel în 3 zile.","es":"Avisas a la agencia de empleo de que tu trabajo termina: al menos 3 meses antes, si no, en 3 días.","ku":"Tu ji ajansa karî re dibêjî ku karê te diqede: herî kêm 3 meh berê, wekî din di nav 3 rojan de."},"x":"Die Arbeitsuchendmeldung ist spätestens drei Monate vor Beendigung des Arbeitsverhältnisses vorzunehmen.","l":"a3","f":true},
{"w":"Steuerklasse","a":"die","c":"arbeit","g":{"tr":"vergi sınıfı","bg":"данъчен клас","ar":"الفئة الضريبية","uk":"податковий клас","pl":"klasa podatkowa","en":"tax class","el":"φορολογική κλάση","fr":"classe d'imposition","nl":"belastingklasse","ro":"clasă de impozitare","es":"clase fiscal","ku":"pola bacê"},"d":{"de":"Sie bestimmt, wie viel Lohnsteuer jeden Monat abgezogen wird. Ehepaare können die Kombination wechseln, z. B. III/V oder IV/IV.","tr":"Her ay ne kadar gelir vergisi kesileceğini belirler. Evli çiftler kombinasyonu değiştirebilir, örneğin III/V veya IV/IV.","bg":"Определя колко данък се удържа всеки месец. Съпрузите могат да сменят комбинацията, напр. III/V или IV/IV.","ar":"تحدد مقدار ضريبة الأجر المقتطعة شهرياً. يمكن للزوجين تغيير التركيبة، مثل III/V أو IV/IV.","uk":"Визначає, скільки податку утримують щомісяця. Подружжя може змінити комбінацію, напр. III/V або IV/IV.","pl":"Określa, ile podatku od wynagrodzenia potrąca się co miesiąc. Małżonkowie mogą zmienić kombinację, np. III/V lub IV/IV.","en":"It decides how much wage tax is deducted each month. Married couples can switch the combination, e.g. III/V or IV/IV.","el":"Καθορίζει πόσος φόρος μισθού παρακρατείται κάθε μήνα. Τα ζευγάρια μπορούν να αλλάξουν συνδυασμό, π.χ. III/V ή IV/IV.","fr":"Elle détermine l'impôt sur le salaire retenu chaque mois. Les couples mariés peuvent changer de combinaison, p. ex. III/V ou IV/IV.","nl":"Bepaalt hoeveel loonbelasting elke maand wordt ingehouden. Echtparen kunnen de combinatie wisselen, bijv. III/V of IV/IV.","ro":"Stabilește cât impozit pe salariu se reține lunar. Soții pot schimba combinația, de ex. III/V sau IV/IV.","es":"Determina cuánto impuesto sobre el salario te retienen al mes. Los matrimonios pueden cambiar la combinación, p. ej. III/V o IV/IV.","ku":"Diyar dike ka her meh çiqas baca meaşê tê birîn. Hevjîn dikarin kombînasyonê biguherînin, wek III/V an IV/IV."},"x":"Ihre Steuerklasse wurde mit Wirkung vom 01.12. geändert.","l":"fa1"},
{"w":"Steuer-Identifikationsnummer","a":"die","c":"arbeit","g":{"tr":"vergi kimlik numarası","bg":"данъчен идентификационен номер","ar":"الرقم الضريبي","uk":"податковий ідентифікаційний номер","pl":"numer identyfikacji podatkowej","en":"tax ID number","el":"αριθμός φορολογικής ταυτότητας","fr":"numéro fiscal","nl":"fiscaal identificatienummer","ro":"cod de identificare fiscală","es":"número de identificación fiscal","ku":"hejmara nasnameya bacê"},"d":{"de":"Ihre persönliche Steuernummer mit 11 Ziffern. Sie bekommen sie nach der ersten Anmeldung per Post; sie gilt ein Leben lang.","tr":"11 haneli kişisel vergi numaranız. İlk kayıttan sonra postayla gelir; ömür boyu geçerlidir.","bg":"Личният ви 11-цифрен данъчен номер. Идва по пощата след първата регистрация и важи цял живот.","ar":"رقمك الضريبي الشخصي من 11 خانة. يصلك بالبريد بعد أول تسجيل ويبقى مدى الحياة.","uk":"Ваш особистий 11-значний податковий номер. Надходить поштою після першої реєстрації й діє все життя.","pl":"Twój osobisty 11-cyfrowy numer podatkowy. Przychodzi pocztą po pierwszym zameldowaniu i obowiązuje dożywotnio.","en":"Your personal 11-digit tax number. It arrives by post after your first registration and is valid for life.","el":"Ο προσωπικός σας 11ψήφιος φορολογικός αριθμός. Έρχεται ταχυδρομικά μετά την πρώτη δήλωση διεύθυνσης και ισχύει δια βίου.","fr":"Votre numéro fiscal personnel à 11 chiffres. Il arrive par courrier après la première déclaration de domicile et vaut à vie.","nl":"Uw persoonlijke belastingnummer van 11 cijfers. U krijgt het per post na de eerste inschrijving; het geldt levenslang.","ro":"Codul fiscal personal din 11 cifre. Vine prin poștă după prima înregistrare și este valabil toată viața.","es":"Tu número fiscal personal de 11 cifras. Llega por correo tras el primer empadronamiento y vale para toda la vida.","ku":"Hejmara te ya bacê ya kesane bi 11 hejmaran. Piştî qeyda yekem bi postê tê û heta dawiya jiyanê derbasdar e."},"x":"Bitte geben Sie Ihre Steuer-Identifikationsnummer an."}];
